// Parse CI failure payload
const body = $json.body || {};
const repo = body.repository?.full_name || body.repo || 'CodeRaksh/Project';
const workflowName = body.workflow || body.job || 'Build & Test';
const commitSha = body.head_commit?.id || body.commit || 'head';
const author = body.sender?.login || body.author || 'dev-team';
const logSnippet = body.log || body.error_message || body.stack_trace || JSON.stringify(body);

return [{
  json: {
    repo: repo,
    workflow: workflowName,
    commit: commitSha.substring(0, 7),
    author: author,
    error_log: logSnippet,
    timestamp: $now.toFormat('dd LLL yyyy, HH:mm:ss')
  }
}];
